Certainly! Below is a complete, self-contained, runnable vanilla JavaScript module for an inventory system with a weight limit and equipment slots that apply stat modifiers. The module includes a self-checking demo at the end.

```javascript
// InventorySystem.js

class Item {
    constructor(name, weight, stats) {
        this.name = name;
        this.weight = weight;
        this.stats = stats; // stats is an object like { strength: 5, agility: -2 }
    }
}

class EquipmentSlot {
    constructor(type) {
        this.type = type; // e.g., 'weapon', 'armor'
        this.item = null;
    }

    equip(item) {
        if (item) {
            console.log(`Equipping ${item.name} to ${this.type} slot.`);
        } else {
            console.log(`Unequipping from ${this.type} slot.`);
        }
        this.item = item;
    }

    getStats() {
        return this.item ? this.item.stats : {};
    }
}

class Inventory {
    constructor(weightLimit) {
        this.items = [];
        this.weightLimit = weightLimit;
        this.equipmentSlots = {
            weapon: new EquipmentSlot('weapon'),
            armor: new EquipmentSlot('armor')
        };
    }

    addItem(item) {
        if (this.totalWeight() + item.weight > this.weightLimit) {
            console.log(`Cannot add ${item.name}: exceeds weight limit.`);
            return false;
        }
        this.items.push(item);
        console.log(`Added ${item.name} to inventory.`);
        return true;
    }

    removeItem(item) {
        const index = this.items.indexOf(item);
        if (index !== -1) {
            this.items.splice(index, 1);
            console.log(`Removed ${item.name} from inventory.`);
            return true;
        }
        console.log(`${item.name} not found in inventory.`);
        return false;
    }

    totalWeight() {
        return this.items.reduce((total, item) => total + item.weight, 0);
    }

    getTotalStats() {
        return Object.values(this.equipmentSlots).reduce((totalStats, slot) => {
            const slotStats = slot.getStats();
            for (const [stat, value] of Object.entries(slotStats)) {
                totalStats[stat] = (totalStats[stat] || 0) + value;
            }
            return totalStats;
        }, {});
    }
}

// Self-checking demo
(function demo() {
    const inventory = new Inventory(10);

    const sword = new Item('Sword', 3, { strength: 5, agility: -2 });
    const shield = new Item('Shield', 4, { defense: 3, agility: -1 });
    const potion = new Item('Health Potion', 1, {});

    console.log("Attempting to add items:");
    inventory.addItem(sword); // Should succeed
    inventory.addItem(shield); // Should succeed
    inventory.addItem(potion); // Should succeed

    console.log("\nCurrent inventory weight:", inventory.totalWeight());
    console.log("Current stats from equipped items:", inventory.getTotalStats());

    console.log("\nEquipping items:");
    inventory.equipmentSlots.weapon.equip(sword);
    inventory.equipmentSlots.armor.equip(shield);

    console.log("\nCurrent stats from equipped items after equipping:", inventory.getTotalStats());

    console.log("\nAttempting to add another heavy item:");
    const heavyArmor = new Item('Heavy Armor', 6, { defense: 8, agility: -3 });
    inventory.addItem(heavyArmor); // Should fail due to weight limit

    console.log("\nRemoving an item:");
    inventory.removeItem(potion); // Should succeed

    console.log("\nAttempting to add the heavy item again:");
    inventory.addItem(heavyArmor); // Should succeed now

    console.log("\nFinal inventory weight:", inventory.totalWeight());
    console.log("Final stats from equipped items:", inventory.getTotalStats());
})();
```

This code defines an `Item` class, an `EquipmentSlot` class, and an `Inventory` class. The `Inventory` class manages a list of items, has a weight limit, and can equip items to specific slots which modify the player's stats. The demo at the end tests various functionalities of the inventory system.

Certainly! Below is a complete, self-contained, runnable vanilla JavaScript module for a turn-based combat system. This module includes functionality for managing initiative order, applying status effects like poison and stun, and a simple demo to verify its correctness.

```javascript
// combatSystem.js

class Character {
    constructor(name, health, attackPower) {
        this.name = name;
        this.health = health;
        this.attackPower = attackPower;
        this.statusEffects = [];
        this.isStunned = false;
    }

    applyStatusEffect(effect) {
        this.statusEffects.push(effect);
    }

    removeStatusEffect(effectName) {
        this.statusEffects = this.statusEffects.filter(effect => effect.name !== effectName);
    }

    takeDamage(amount) {
        this.health -= amount;
        if (this.health < 0) this.health = 0;
    }

    applyTurnEffects() {
        this.statusEffects.forEach(effect => {
            if (effect.type === 'poison') {
                this.takeDamage(effect.damage);
                console.log(`${this.name} takes ${effect.damage} damage from poison.`);
            }
            if (effect.type === 'stun') {
                this.isStunned = true;
                console.log(`${this.name} is stunned and cannot act.`);
            }
        });
    }

    endTurn() {
        this.statusEffects = this.statusEffects.map(effect => {
            effect.duration--;
            return effect;
        }).filter(effect => effect.duration > 0);

        this.isStunned = false;
    }
}

class CombatSystem {
    constructor() {
        this.characters = [];
        this.initiativeOrder = [];
    }

    addCharacter(character) {
        this.characters.push(character);
    }

    determineInitiative() {
        this.initiativeOrder = this.characters.slice().sort(() => Math.random() - 0.5);
        console.log('Initiative Order:', this.initiativeOrder.map(char => char.name).join(', '));
    }

    startCombat() {
        this.determineInitiative();
        let combatRound = 1;

        while (this.characters.some(char => char.health > 0)) {
            console.log(`\nRound ${combatRound}:`);
            this.initiativeOrder.forEach(character => {
                if (character.health <= 0) return;
                character.applyTurnEffects();

                if (character.isStunned) return;

                const target = this.getRandomLivingEnemy(character);
                if (target) {
                    target.takeDamage(character.attackPower);
                    console.log(`${character.name} attacks ${target.name} for ${character.attackPower} damage.`);
                }

                character.endTurn();
            });

            combatRound++;
        }

        const winner = this.characters.find(char => char.health > 0);
        console.log(`\n${winner ? winner.name : 'No one'} wins the battle!`);
    }

    getRandomLivingEnemy(attacker) {
        const enemies = this.characters.filter(char => char !== attacker && char.health > 0);
        return enemies.length > 0 ? enemies[Math.floor(Math.random() * enemies.length)] : null;
    }
}

// Demo
const combatSystem = new CombatSystem();

const hero = new Character('Hero', 100, 20);
const goblin = new Character('Goblin', 50, 10);
const orc = new Character('Orc', 75, 15);

hero.applyStatusEffect({ name: 'poison', type: 'poison', damage: 5, duration: 3 });
orc.applyStatusEffect({ name: 'stun', type: 'stun', duration: 1 });

combatSystem.addCharacter(hero);
combatSystem.addCharacter(goblin);
combatSystem.addCharacter(orc);

combatSystem.startCombat();
```

### Explanation:
- **Character Class**: Represents a character in the combat system with properties for health, attack power, and status effects.
- **CombatSystem Class**: Manages the combat flow, including determining initiative order and handling turns.
- **Demo**: Sets up a simple combat scenario with three characters, applies some status effects, and starts the combat.

This code can be run in any JavaScript environment, such as a browser's developer console or Node.js. The demo will print the combat log to the console, showing each round of the battle and the outcome.

Certainly! Below is a complete, self-contained, runnable vanilla JavaScript module that implements a simple crafting system. This system allows you to define recipes, manage an inventory, and craft items based on those recipes. It also includes a self-checking demo at the end.

```javascript
// CraftingSystem.js

class CraftingSystem {
    constructor() {
        this.recipes = {};
        this.inventory = {};
    }

    addRecipe(name, ingredients, result) {
        if (this.recipes[name]) {
            console.warn(`Recipe for ${name} already exists. Overwriting.`);
        }
        this.recipes[name] = { ingredients, result };
    }

    addItemToInventory(itemName, quantity) {
        if (!this.inventory[itemName]) {
            this.inventory[itemName] = 0;
        }
        this.inventory[itemName] += quantity;
    }

    canCraft(recipeName) {
        const recipe = this.recipes[recipeName];
        if (!recipe) {
            console.error(`No recipe found for ${recipeName}`);
            return false;
        }

        for (const [ingredient, requiredQuantity] of Object.entries(recipe.ingredients)) {
            if ((this.inventory[ingredient] || 0) < requiredQuantity) {
                return false;
            }
        }
        return true;
    }

    craft(recipeName) {
        if (!this.canCraft(recipeName)) {
            console.error(`Cannot craft ${recipeName}. Missing ingredients.`);
            return null;
        }

        const recipe = this.recipes[recipeName];
        for (const [ingredient, requiredQuantity] of Object.entries(recipe.ingredients)) {
            this.inventory[ingredient] -= requiredQuantity;
        }

        const resultItem = recipe.result;
        this.addItemToInventory(resultItem.name, resultItem.quantity);
        console.log(`Crafted ${resultItem.quantity}x ${resultItem.name}`);
        return resultItem;
    }

    getInventory() {
        return this.inventory;
    }
}

// Self-checking demo
(function demo() {
    const craftingSystem = new CraftingSystem();

    // Adding recipes
    craftingSystem.addRecipe('Wooden Sword', { 'Wood': 2, 'Stone': 1 }, { name: 'Wooden Sword', quantity: 1 });
    craftingSystem.addRecipe('Iron Sword', { 'Iron': 3, 'Wood': 1 }, { name: 'Iron Sword', quantity: 1 });

    // Adding items to inventory
    craftingSystem.addItemToInventory('Wood', 5);
    craftingSystem.addItemToInventory('Stone', 3);
    craftingSystem.addItemToInventory('Iron', 4);

    // Crafting items
    console.log('Attempting to craft Wooden Sword...');
    craftingSystem.craft('Wooden Sword');
    console.log('Inventory after crafting Wooden Sword:', craftingSystem.getInventory());

    console.log('Attempting to craft Iron Sword...');
    craftingSystem.craft('Iron Sword');
    console.log('Inventory after crafting Iron Sword:', craftingSystem.getInventory());

    // Attempting to craft again with insufficient materials
    console.log('Attempting to craft another Iron Sword...');
    craftingSystem.craft('Iron Sword');
    console.log('Inventory after attempting to craft another Iron Sword:', craftingSystem.getInventory());
})();
```

This script defines a `CraftingSystem` class with methods to add recipes, add items to the inventory, check if a recipe can be crafted, craft an item, and get the current inventory state. The demo function at the end sets up some recipes and inventory items, attempts to craft items, and logs the results to the console.

