// StatusEffectSystem.js

class StatusEffect {
    constructor(name, duration, stackLimit = 1, onExpiry = () => {}) {
        this.name = name;
        this.duration = duration;
        this.stackLimit = stackLimit;
        this.onExpiry = onExpiry;
        this.stacks = 0;
    }

    apply() {
        if (this.stacks < this.stackLimit) {
            this.stacks++;
            return true;
        }
        return false;
    }

    tick() {
        if (this.stacks > 0) {
            this.duration--;
            if (this.duration <= 0) {
                this.expiry();
            }
        }
    }

    expiry() {
        this.onExpiry(this);
        this.stacks = 0;
        this.duration = 0;
    }
}

class StatusEffectSystem {
    constructor(tickInterval = 1000) {
        this.effects = {};
        this.tickInterval = tickInterval;
        this.timer = null;
    }

    addEffect(effect) {
        if (!this.effects[effect.name]) {
            this.effects[effect.name] = effect;
        }
        this.effects[effect.name].apply();
    }

    start() {
        this.timer = setInterval(() => {
            for (const effectName in this.effects) {
                const effect = this.effects[effectName];
                effect.tick();
            }
        }, this.tickInterval);
    }

    stop() {
        clearInterval(this.timer);
    }
}

