    system.addEffect(burn);
    system.addEffect(poison);
    system.addEffect(poison);
    system.addEffect(poison); // This should not stack

    log('Starting effect system...');
    system.start();

    setTimeout(() => {
        log('Stopping effect system...');
        system.stop();
    }, 10000); // Stop the system after 10 seconds to see the effects expire
})();
