// SpatialHashGrid.js

class SpatialHashGrid {
    constructor(cellSize) {
        this.cellSize = cellSize;
        this.grid = new Map();
    }

    _getHash(x, y) {
        const cellX = Math.floor(x / this.cellSize);
        const cellY = Math.floor(y / this.cellSize);
        return `${cellX},${cellY}`;
    }

    insert(obj, x, y) {
        const hash = this._getHash(x, y);
        if (!this.grid.has(hash)) {
            this.grid.set(hash, []);
        }
        this.grid.get(hash).push({ obj, x, y });
    }

    queryRegion(x, y, width, height) {
        const results = [];
        const startX = Math.floor(x / this.cellSize);
        const startY = Math.floor(y / this.cellSize);
        const endX = Math.floor((x + width) / this.cellSize);
        const endY = Math.floor((y + height) / this.cellSize);

        for (let i = startX; i <= endX; i++) {
            for (let j = startY; j <= endY; j++) {
                const hash = `${i},${j}`;
                if (this.grid.has(hash)) {
                    this.grid.get(hash).forEach(entry => {
                        if (entry.x >= x && entry.x < x + width &&
                            entry.y >= y && entry.y < y + height) {
                            results.push(entry.obj);
                        }
                    });
                }
            }
        }
        return results;
    }

    clear() {
        this.grid.clear();
    }
}

