// Event Bus Module
class EventBus {
    constructor() {
        this.events = {};
    }

    on(eventName, handler) {
        if (!this.events[eventName]) {
            this.events[eventName] = [];
        }
        this.events[eventName].push(handler);
        return () => this.off(eventName, handler);
    }

    off(eventName, handler) {
        if (this.events[eventName]) {
            this.events[eventName] = this.events[eventName].filter(h => h !== handler);
        }
    }

    once(eventName, handler) {
        const onceHandler = (...args) => {
            handler(...args);
            this.off(eventName, onceHandler);
        };
        return this.on(eventName, onceHandler);
    }

    emit(eventName, ...args) {
        if (this.events[eventName]) {
            // Create a copy of the handlers array to avoid issues with modification during iteration
            const handlers = [...this.events[eventName]];
            handlers.forEach(handler => handler(...args));
        }
    }
}

// Self-checking demo
(function() {
    const eventBus = new EventBus();

    // Test on and emit
    let countOn = 0;
    const handlerOn = () => countOn++;
    eventBus.on('testEvent', handlerOn);
    eventBus.emit('testEvent');
    console.assert(countOn === 1, 'Test 1 Failed: "on" and "emit" should work correctly.');

    // Test off
    eventBus.off('testEvent', handlerOn);
    eventBus.emit('testEvent');
    console.assert(countOn === 1, 'Test 2 Failed: "off" should remove the handler.');

    // Test once
    let countOnce = 0;
    eventBus.once('testEventOnce', () => countOnce++);
    eventBus.emit('testEventOnce');
    console.assert(countOnce === 1, 'Test 3 Failed: "once" should trigger the handler only once.');
    eventBus.emit('testEventOnce');
    console.assert(countOnce === 1, 'Test 4 Failed: "once" should not trigger the handler again.');

    // Test unsubscribe during emit
    let countDuringEmit = 0;
    const handlerDuringEmit = () => {
        countDuringEmit++;
        eventBus.off('testEventDuringEmit', handlerDuringEmit);
    };
    eventBus.on('testEventDuringEmit', handlerDuringEmit);
    eventBus.emit('testEventDuringEmit');
    console.assert(countDuringEmit === 1, 'Test 5 Failed: Handler should unsubscribe safely during emit.');

    console.log('All tests passed!');
})();
```

