// Seeded PRNG using Linear Congruential Generator (LCG) algorithm
class SeededPRNG {
    constructor(seed) {
        this.seed = seed;
    }

    next() {
        // LCG parameters from Numerical Recipes
        const m = 0x80000000; // 2**31
        const a = 1103515245;
        const c = 12345;
        this.seed = (a * this.seed + c) % m;
        return this.seed / (m - 1);
    }
}

// Weighted Loot Table class
class WeightedLootTable {
    constructor(items, weights, seed) {
        if (items.length !== weights.length) {
            throw new Error("Items and weights must have the same length.");
        }
        this.prng = new SeededPRNG(seed);
        this.items = items;
        this.weights = weights;
        this.totalWeight = this.weights.reduce((sum, weight) => sum + weight, 0);
    }

    pick() {
        const randomValue = this.prng.next() * this.totalWeight;
        let cumulativeWeight = 0;

        for (let i = 0; i < this.items.length; i++) {
            cumulativeWeight += this.weights[i];
            if (randomValue < cumulativeWeight) {
                return this.items[i];
            }
        }

        // Fallback to last item if something goes wrong (shouldn't happen)
        return this.items[this.items.length - 1];
    }
}

