    constructor(maxCharges, rechargeTime) {
        this.maxCharges = maxCharges; // Maximum number of charges
        this.rechargeTime = rechargeTime; // Time in milliseconds to recharge one charge
        this.currentCharges = maxCharges; // Current number of charges
        this.rechargeIntervals = []; // Array to hold interval IDs for recharging
    }

    useCharge() {
        if (this.currentCharges > 0) {
            this.currentCharges -= 1;
