// TileMap.js

class TileMap {
    constructor(width, height) {
        this.width = width;
        this.height = height;
        this.map = Array.from({ length: height }, () => Array(width).fill(0));
    }

    setTile(x, y, value) {
        if (x >= 0 && x < this.width && y >= 0 && y < this.height) {
            this.map[y][x] = value;
        }
    }

    getTile(x, y) {
        if (x >= 0 && x < this.width && y >= 0 && y < this.height) {
            return this.map[y][x];
        }
        return -1; // Out of bounds
    }

    floodFill(startX, startY, targetValue, newValue) {
        const queue = [[startX, startY]];
        const visited = new Set();

        while (queue.length > 0) {
            const [x, y] = queue.shift();
            if (visited.has(`${x},${y}`)) continue;
            visited.add(`${x},${y}`);

            if (this.getTile(x, y) === targetValue) {
                this.setTile(x, y, newValue);

                // Check all 4 directions
                [[x + 1, y], [x - 1, y], [x, y + 1], [x, y - 1]].forEach(([nx, ny]) => {
                    if (nx >= 0 && nx < this.width && ny >= 0 && ny < this.height) {
                        queue.push([nx, ny]);
                    }
                });
            }
        }
    }

    lineOfSight(startX, startY, endX, endY) {
        const dx = Math.abs(endX - startX);
        const dy = Math.abs(endY - startY);
        const sx = startX < endX ? 1 : -1;
        const sy = startY < endY ? 1 : -1;
        let err = dx - dy;

        while (true) {
            if (this.getTile(startX, startY) !== 0) {
                return false; // Blocked by an obstacle
            }
            if (startX === endX && startY === endY) {
                return true; // Reached the end point
            }
            const e2 = 2 * err;
            if (e2 > -dy) {
                err -= dy;
                startX += sx;
            }
            if (e2 < dx) {
                err += dx;
                startY += sy;
            }
        }
    }

    printMap() {
        console.log(this.map.map(row => row.join(' ')).join('\n'));
    }
}

// Self-checking demo
