        map.setTile(x, 5, 1);
    }

    console.log("Initial Map:");
    map.printMap();

    // Flood fill starting from (0, 0) with target value 0 and new value 2
    map.floodFill(0, 0, 0, 2);

    console.log("\nAfter Flood Fill:");
    map.printMap();

    // Check line of sight from (0, 0) to (9, 9)
    console.log("\nLine of Sight from (0, 0) to (9, 9):", map.lineOfSight(0, 0, 9, 9));

