// Module: UndoRedoManager.js

class UndoRedoManager {
    constructor() {
        this.history = [];
        this.future = [];
        this.currentState = null;
    }

    setState(state) {
        if (this.currentState !== null) {
            this.history.push(this.currentState);
            this.future = []; // Clear future when new state is set
        }
        this.currentState = state;
    }

    undo() {
        if (this.history.length === 0) return null; // No more states to undo
        this.future.push(this.currentState);
        this.currentState = this.history.pop();
        return this.currentState;
    }

    redo() {
        if (this.future.length === 0) return null; // No more states to redo
        this.history.push(this.currentState);
        this.currentState = this.future.pop();
        return this.currentState;
    }

    getCurrentState() {
        return this.currentState;
    }
}

// Demo: Self-checking demonstration of the UndoRedoManager

function runDemo() {
    const manager = new UndoRedoManager();
    console.log("Initial State:", manager.getCurrentState()); // Should be null

    manager.setState("State 1");
    console.log("After setting State 1:", manager.getCurrentState()); // Should be "State 1"

    manager.setState("State 2");
    console.log("After setting State 2:", manager.getCurrentState()); // Should be "State 2"

    manager.undo();
    console.log("After undoing:", manager.getCurrentState()); // Should be "State 1"

    manager.redo();
    console.log("After redoing:", manager.getCurrentState()); // Should be "State 2"

    manager.undo();
    manager.undo();
    console.log("After undoing twice:", manager.getCurrentState()); // Should be null

    manager.redo();
    console.log("After redoing once:", manager.getCurrentState()); // Should be "State 1"

