        damage *= (1 - resistance);
        return damage;
    }

    calculateTotalDamage(resistance) {
        let totalDamage = 0;
        // Calculate initial hit damage
        totalDamage += this.calculateDamage(resistance);
        // Calculate DoT damage
        for (let i = 0; i < this.dotDuration; i++) {
            totalDamage += this.dotDamage * (1 - resistance);
        }
        return totalDamage;
    }
}

// Self-checking demo
