// InGameClock.js

class InGameClock {
    constructor(dayLength) {
        this.dayLength = dayLength; // Total length of a day in milliseconds
        this.currentTime = 0; // Current time in the game clock
        this.callbacks = []; // List of callbacks with their scheduled times
        this.running = false; // Flag to check if the clock is running
        this.currentPhase = 'Dawn'; // Initial phase
        this.phases = {
            Dawn: 0,
            Morning: dayLength * 0.25,
            Noon: dayLength * 0.5,
            Afternoon: dayLength * 0.75,
            Dusk: dayLength * 0.9,
            Night: dayLength
        };
    }

    start() {
        if (this.running) return;
        this.running = true;
        this.tick();
    }

    stop() {
        this.running = false;
    }

    tick() {
        if (!this.running) return;

        setTimeout(() => {
            this.currentTime += 100; // Simulate passing of time
            this.checkCallbacks();
            this.updatePhase();
            this.tick(); // Recursive call for continuous ticking
        }, 100);
    }

    scheduleCallback(callback, time) {
        if (time < this.currentTime || time > this.currentTime + this.dayLength) {
            throw new Error('Invalid callback time');
        }
        this.callbacks.push({ time, callback });
        this.callbacks.sort((a, b) => a.time - b.time); // Ensure callbacks are sorted by time
    }

    checkCallbacks() {
        while (this.callbacks.length && this.callbacks[0].time <= this.currentTime) {
            const { callback } = this.callbacks.shift();
            callback(this.currentTime);
        }
    }

    updatePhase() {
        const phaseKeys = Object.keys(this.phases);
        for (let i = 0; i < phaseKeys.length; i++) {
            if (this.currentTime < this.phases[phaseKeys[i]]) {
                if (this.currentPhase !== phaseKeys[i - 1]) {
                    this.currentPhase = phaseKeys[i - 1];
                    console.log(`Entering phase: ${this.currentPhase}`);
                }
                break;
            }
        }
        if (this.currentTime >= this.phases.Night) {
            this.currentPhase = 'Night';
            console.log(`Entering phase: ${this.currentPhase}`);
            this.currentTime = 0; // Reset time to start a new day
        }
    }
}

// Self-checking demo
(function demo() {
    const dayLength = 4000; // 4 seconds per day for demonstration purposes
    const clock = new InGameClock(dayLength);

    clock.scheduleCallback((time) => console.log(`Callback at ${time}ms: Good morning!`), dayLength * 0.25);
    clock.scheduleCallback((time) => console.log(`Callback at ${time}ms: Time for lunch!`), dayLength * 0.5);
    clock.scheduleCallback((time) => console.log(`Callback at ${time}ms: Time for dinner!`), dayLength * 0.75);
    clock.scheduleCallback((time) => console.log(`Callback at ${time}ms: Time to sleep!`), dayLength * 0.9);

    clock.start();

    // Stop the clock after 12 seconds to prevent it from running indefinitely in the demo
    setTimeout(() => {
        clock.stop();
        console.log('Demo ended.');
    }, 12000);
})();
```

