```javascript
// FactionReputationSystem.js

class FactionReputationSystem {
    constructor() {
        this.factions = {
            'FactionA': 0,
            'FactionB': 0
        };
    }

    helpFaction(factionName) {
        if (!this.factions.hasOwnProperty(factionName)) {
            throw new Error(`Unknown faction: ${factionName}`);
        }

        // Increase reputation with the helped faction
        this.factions[factionName] += 1;

        // Decrease reputation with the rival faction
        const rivalFaction = factionName === 'FactionA' ? 'FactionB' : 'FactionA';
        this.factions[rivalFaction] -= 1;
    }

    getReputation(factionName) {
        if (!this.factions.hasOwnProperty(factionName)) {
            throw new Error(`Unknown faction: ${factionName}`);
        }
        return this.factions[factionName];
    }

    resetReputations() {
        this.factions['FactionA'] = 0;
        this.factions['FactionB'] = 0;
    }
}

// Self-checking demo
function runDemo() {
    const system = new FactionReputationSystem();

    console.log("Initial reputations:");
    console.log(`FactionA: ${system.getReputation('FactionA')}`); // Expected: 0
    console.log(`FactionB: ${system.getReputation('FactionB')}`); // Expected: 0

    console.log("\nHelping FactionA three times...");
    system.helpFaction('FactionA');
    system.helpFaction('FactionA');
    system.helpFaction('FactionA');

    console.log(`FactionA: ${system.getReputation('FactionA')}`); // Expected: 3
    console.log(`FactionB: ${system.getReputation('FactionB')}`); // Expected: -3

    console.log("\nHelping FactionB once...");
    system.helpFaction('FactionB');

    console.log(`FactionA: ${system.getReputation('FactionA')}`); // Expected: 2
    console.log(`FactionB: ${system.getReputation('FactionB')}`); // Expected: -2

    console.log("\nResetting reputations...");
    system.resetReputations();

    console.log(`FactionA: ${system.getReputation('FactionA')}`); // Expected: 0
    console.log(`FactionB: ${system.getReputation('FactionB')}`); // Expected: 0
}

// Run the demo
runDemo();
```

This code defines a `FactionReputationSystem` class that manages the reputation of two factions. The `helpFaction` method increases the reputation of the specified faction and decreases the reputation of the rival faction. The `getReputation` method returns the current reputation of a specified faction, and `resetReputations` resets both factions' reputations to zero. The `runDemo` function demonstrates the functionality of the system.

