```javascript
// Main game configuration
const config = {
    type: Phaser.AUTO,
    width: 800,
    height: 600,
    physics: {
        default: 'arcade',
        arcade: {
            gravity: { y: 0 },
            debug: false
        }
    },
    scene: {
        preload: preload,
        create: create,
        update: update
    }
};

const game = new Phaser.Game(config);

let player;
let bullets;
let enemies;
let lastFired = 0;
const BULLET_SPEED = 500;
const ENEMY_SPEED = 100;
const FIRE_RATE = 200;

function preload() {
    this.load.image('player', 'https://labs.phaser.io/assets/sprites/phaser-dude.png');
    this.load.image('bullet', 'https://labs.phaser.io/assets/sprites/bullet.png');
    this.load.image('enemy', 'https://labs.phaser.io/assets/sprites/enemy-bug.png');
}

function create() {
    // Create player
    player = this.physics.add.sprite(400, 300, 'player').setScale(0.5);
    player.setCollideWorldBounds(true);

    // Create bullet group
    bullets = this.physics.add.group({
        defaultKey: 'bullet',
        maxSize: 30,
        runChildUpdate: true
    });

    // Create enemy group
    enemies = this.physics.add.group({
        defaultKey: 'enemy',
        maxSize: 20,
        runChildUpdate: true
    });

    // Spawn enemies
    this.time.addEvent({
        delay: 1000,
        callback: spawnEnemy,
        callbackScope: this,
        loop: true
    });

    // Input handling
    this.input.on('pointermove', function (pointer) {
        const angle = Phaser.Math.Angle.Between(player.x, player.y, pointer.worldX, pointer.worldY);
        player.rotation = angle;
    }, this);

    this.input.on('pointerdown', fireBullet, this);
}

function update(time, delta) {
    // Move enemies towards player
    enemies.children.iterate(function (enemy) {
        if (enemy.active) {
            const angle = Phaser.Math.Angle.Between(enemy.x, enemy.y, player.x, player.y);
            enemy.rotation = angle + Math.PI / 2; // Adjust rotation to face player
            this.physics.moveToObject(enemy, player, ENEMY_SPEED);
        }
    }, this);

    // Check for collisions between bullets and enemies
    this.physics.world.collide(bullets, enemies, hitEnemy, null, this);
}

function fireBullet() {
    if (time > lastFired) {
        const bullet = bullets.get();
        if (bullet) {
            bullet.setActive(true);
            bullet.setVisible(true);
            bullet.setPosition(player.x, player.y);
            bullet.setRotation(player.rotation);
            this.physics.velocityFromRotation(player.rotation, BULLET_SPEED, bullet.body.velocity);
            lastFired = time + FIRE_RATE;
        }
    }
}

function spawnEnemy() {
    const x = Phaser.Math.Between(0, game.config.width);
    const y = Phaser.Math.Between(0, game.config.height);
    if (x === 0 || x === game.config.width) {
        y = Phaser.Math.Between(0, game.config.height);
    } else {
        x = Phaser.Math.Between(0, game.config.width);
    }

    const enemy = enemies.get(x, y);
    if (enemy) {
        enemy.setActive(true);
        enemy.setVisible(true);
    }
}

function hitEnemy(bullet, enemy) {
    bullet.setActive(false);
    bullet.setVisible(false);
    enemy.setActive(false);
    enemy.setVisible(false);
}
```

### Explanation:
- **Player**: The player sprite is controlled by the mouse pointer's position. It rotates to face the pointer.
- **Bullets**: When the player clicks, a bullet is fired in the direction the player is facing.
- **Enemies**: Enemies spawn randomly at the edges of the screen and move towards the player.
- **Collision Detection**: Bullets collide with enemies, deactivating both upon collision.

