    [tile1.row, tile2.row] = [tile2.row, tile1.row];
    [tile1.col, tile2.col] = [tile2.col, tile1.col];
    [tileGrid[tile1.row][tile1.col], tileGrid[tile2.row][tile2.col]] = [tileGrid[tile2.row][tile2.col], tileGrid[tile1.row][tile1.col]];
}

function checkForMatches() {
    let matchesFound = false;

    // Check horizontal matches
    for (let row = 0; row < gridSize.rows; row++) {
        let matchLength = 1;
        for (let col = 1; col < gridSize.cols; col++) {
            if (tileGrid[row][col].color === tileGrid[row][col - 1].color) {
                matchLength++;
            } else {
                if (matchLength >= 3) {
                    removeMatch(row, col - matchLength, col - 1, 'horizontal');
                    matchesFound = true;
                }
                matchLength = 1;
            }
        }
        if (matchLength >= 3) {
            removeMatch(row, gridSize.cols - matchLength, gridSize.cols - 1, 'horizontal');
            matchesFound = true;
        }
    }

    // Check vertical matches
    for (let col = 0; col < gridSize.cols; col++) {
        let matchLength = 1;
        for (let row = 1; row < gridSize.rows; row++) {
            if (tileGrid[row][col].color === tileGrid[row - 1][col].color) {
                matchLength++;
            } else {
                if (matchLength >= 3) {
                    removeMatch(row - matchLength, col, row - 1, 'vertical');
                    matchesFound = true;
                }
                matchLength = 1;
            }
        }
        if (matchLength >= 3) {
            removeMatch(gridSize.rows - matchLength, col, gridSize.rows - 1, 'vertical');
            matchesFound = true;
        }
    }

    if (matchesFound) {
        this.time.delayedCall(500, checkForMatches, [], this);
    }
}

function removeMatch(startRow, col, endRow, direction) {
    let points = 0;
    for (let i = startRow; i <= endRow; i++) {
        const tile = tileGrid[i][col];
        tile.destroy();
        tileGrid[i][col] = null;
        points += 10;
    }
    score += points;
    this.scoreText.setText('Score: ' + score);

    // Drop tiles above the removed ones
    for (let i = endRow - 1; i >= 0; i--) {
        for (let j = col; j <= col; j++) {
            if (tileGrid[i][j]) {
                const tile = tileGrid[i][j];
                tileGrid[i][j] = null;
                tileGrid[i + (endRow - i)][j] = tile;
                tile.row = i + (endRow - i);
                this.tweens.add({
                    targets: tile,
                    y: tile.y + (endRow - i) * tileSize,
                    duration: 200,
                    ease: 'Linear'
                });
            }
        }
    }

    // Fill empty spaces with new tiles
    for (let i = 0; i < gridSize.rows; i++) {
        for (let j = col; j <= col; j++) {
            if (!tileGrid[i][j]) {
                const color = colors[Phaser.Math.Between(0, colors.length - 1)];
                const tile = this.add.rectangle(j * tileSize + 50, i * tileSize + 50, tileSize, tileSize, color);
                tile.setInteractive();
                tile.row = i;
                tile.col = j;
                tile.color = color;
                tileGrid[i][j] = tile;
            }
        }
    }
}
```

This code sets up a basic Phaser 3 game with a grid of colored tiles. When you click on two adjacent tiles, they swap places. If the swap results in three or more tiles of the same color being aligned horizontally or vertically, those tiles disappear, and new tiles fall from the top to fill the gaps. The score increases based on the number of tiles cleared.

