    this.ball.setVelocity(200, -200);
    this.ball.setCollideWorldBounds(true);
    this.ball.body.onWorldBounds = true;
    this.ball.world.on('worldbounds', this.handleBallWorldCollision, this);

    // Create a group for bricks
    this.bricks = this.physics.add.staticGroup({
        key: 'brick',
        frameQuantity: 50,
        gridAlign: { width: 10, height: 5, cellWidth: 64, cellHeight: 32, x: 112, y: 50 }
    });

    // Set collision between ball and paddle
    this.physics.add.collider(this.ball, this.paddle);

    // Set collision between ball and bricks
    this.physics.add.collider(this.ball, this.bricks, this.hitBrick, null, this);

    // Make the paddle follow the mouse pointer
    this.input.on('pointermove', function (pointer) {
        this.paddle.x = pointer.x;
    }, this);
}

function update() {
    // Check if the ball goes out of bounds at the bottom
    if (this.ball.y > 600) {
        this.scene.restart(); // Restart the scene if the ball falls off the screen
    }
}

function handleBallWorldCollision(ball, up, down, left, right) {
    if (down) {
        this.scene.restart(); // Restart the scene if the ball hits the bottom
    }
}

function hitBrick(ball, brick) {
    brick.destroy(); // Destroy the brick when hit by the ball
}
