Certainly! Below is a complete Phaser 3 program for a simple Snake game. The snake moves on a grid, eats pellets to grow, and the game restarts if the snake collides with itself.

```javascript
// Define the main game configuration
const config = {
    type: Phaser.AUTO,
    width: 400,
    height: 400,
    backgroundColor: '#222',
    scene: {
        preload: preload,
        create: create,
        update: update
    }
};

// Create a new Phaser game instance
const game = new Phaser.Game(config);

let snake;
let food;
let cursors;
let speed = 10;
let direction = { x: 0, y: 0 };
let newDirection = { x: 0, y: 0 };
let grid = 20;
let gameOver = false;

function preload() {
    // Load assets here if needed
}

function create() {
    // Initialize the snake
    snake = this.add.group();
    snake.create(160, 160, 'snake').setOrigin(0);
    snake.create(140, 160, 'snake').setOrigin(0);
    snake.create(120, 160, 'snake').setOrigin(0);

    // Initialize the food
    food = this.add.rectangle(80, 80, grid, grid, 0xff0000).setOrigin(0);

    // Set up physics
    this.physics.world.setBounds(0, 0, 400, 400);
    snake.children.iterate(child => {
        this.physics.add.existing(child);
        child.body.setCollideWorldBounds(true);
    });

    // Set up input
    cursors = this.input.keyboard.createCursorKeys();

    // Start the game loop
    this.time.addEvent({
        delay: 150,
        callback: moveSnake,
        callbackScope: this,
        loop: true
    });
}

function update() {
    // Update direction based on cursor keys
    if (cursors.right.isDown && direction.x === 0) {
        newDirection = { x: 1, y: 0 };
    } else if (cursors.left.isDown && direction.x === 0) {
        newDirection = { x: -1, y: 0 };
    } else if (cursors.down.isDown && direction.y === 0) {
        newDirection = { x: 0, y: 1 };
    } else if (cursors.up.isDown && direction.y === 0) {
        newDirection = { x: 0, y: -1 };
    }

    // Check for collisions with the snake's body
    let head = snake.getFirst(true);
    snake.children.iterate(child => {
        if (child !== head && head.x === child.x && head.y === child.y) {
            gameOver = true;
        }
    });

    // Check for collision with food
    if (head.x === food.x && head.y === food.y) {
        growSnake();
        placeFood();
    }

    // Game over condition
    if (gameOver) {
        resetGame(this);
    }
}

function moveSnake() {
    if (newDirection.x !== 0 || newDirection.y !== 0) {
        direction = newDirection;
    }

    let head = snake.getFirst(true);
    let nextX = head.x + direction.x * grid;
    let nextY = head.y + direction.y * grid;

    // Move the snake by removing the tail and adding a new head at the front
    let tail = snake.getLast(true);
    snake.remove(tail, true, true);

    let newHead = this.add.rectangle(nextX, nextY, grid, grid, 0x00ff00).setOrigin(0);
    this.physics.add.existing(newHead);
    newHead.body.setCollideWorldBounds(true);
    snake.add(newHead);
}

function growSnake() {
    let tail = snake.getLast(true);
    let newTail = this.add.rectangle(tail.x, tail.y, grid, grid, 0x00ff00).setOrigin(0);
    this.physics.add.existing(newTail);
    newTail.body.setCollideWorldBounds(true);
    snake.add(newTail);
}

function placeFood() {
    let x = Phaser.Math.Between(0, 19) * grid;
    let y = Phaser.Math.Between(0, 19) * grid;
    food.setPosition(x, y);
}

function resetGame(scene) {
    snake.clear(true, true);
    snake.create(160, 160, 'snake').setOrigin(0);
    snake.create(140, 160, 'snake').setOrigin(0);
    snake.create(120, 160, 'snake').setOrigin(0);
    placeFood();
    direction = { x: 0, y: 0 };
    newDirection = { x: 0, y: 0 };
    gameOver = false;
}
```

### Explanation:
- **Grid System**: The game uses a 20x20 grid system where each cell is 20x20 pixels.
- **Snake Movement**: The snake moves in the direction of the arrow keys pressed. It changes direction only when the current movement is not in the opposite direction.
- **Collision Detection**: The game checks for collisions with the snake's body and the food. If the snake collides with itself, the game resets.
- **Food Placement**: Food is randomly placed on the grid, and the snake grows when it eats the food.
- **Game Over**: When the snake collides with itself, the game resets the snake's position and size.

