Certainly! Below is a complete Phaser 3 program where you can place towers by clicking on the screen. These towers will automatically fire at enemies that walk along a fixed path.

```javascript
// Main game configuration
const config = {
    type: Phaser.AUTO,
    width: 800,
    height: 600,
    physics: {
        default: 'arcade',
        arcade: {
            gravity: { y: 0 },
            debug: false
        }
    },
    scene: {
        preload: preload,
        create: create,
        update: update
    }
};

const game = new Phaser.Game(config);

let towers = [];
let enemies = [];
let towerRange = 150;
let towerFireRate = 1000; // milliseconds
let lastFired = 0;

function preload() {
    this.load.image('tower', 'https://labs.phaser.io/assets/sprites/platformer-pack/tower.png');
    this.load.image('enemy', 'https://labs.phaser.io/assets/sprites/bunny.png');
    this.load.image('bullet', 'https://labs.phaser.io/assets/sprites/diamond.png');
}

function create() {
    // Set up the input for placing towers
    this.input.on('pointerdown', placeTower, this);

    // Create a group for bullets
    this.bullets = this.physics.add.group({
        key: 'bullet',
        active: false,
        visible: false,
        max: 100,
        collideWorldBounds: true,
        bounceX: 1,
        bounceY: 1
    });

    // Start spawning enemies
    this.time.addEvent({
        delay: 2000,
        callback: spawnEnemy,
        callbackScope: this,
        loop: true
    });
}

function update(time, delta) {
    // Check if any tower can fire
    towers.forEach(tower => {
        let nearestEnemy = findNearestEnemy(tower);
        if (nearestEnemy && Phaser.Math.Distance.Between(tower.x, tower.y, nearestEnemy.x, nearestEnemy.y) <= towerRange) {
            if (time > lastFired + towerFireRate) {
                fireBullet(tower, nearestEnemy);
                lastFired = time;
            }
        }
    });

    // Move enemies along the path
    enemies.forEach(enemy => {
        // Simple linear movement towards the end of the screen
        enemy.x += 1;
        if (enemy.x > this.cameras.main.width) {
            enemy.destroy();
            enemies = enemies.filter(e => e !== enemy);
        }
    });
}

function placeTower(pointer) {
    const tower = this.physics.add.sprite(pointer.x, pointer.y, 'tower');
    towers.push(tower);
}

function spawnEnemy() {
    const enemy = this.physics.add.sprite(0, 300, 'enemy');
    enemies.push(enemy);
}

function findNearestEnemy(tower) {
    let nearest = null;
    let minDistance = Infinity;

    enemies.forEach(enemy => {
        const distance = Phaser.Math.Distance.Between(tower.x, tower.y, enemy.x, enemy.y);
        if (distance < minDistance) {
            minDistance = distance;
            nearest = enemy;
        }
    });

    return nearest;
}

function fireBullet(tower, target) {
    const bullet = this.bullets.get();
    if (bullet) {
        bullet.setActive(true);
        bullet.setVisible(true);
        bullet.setPosition(tower.x, tower.y);
        this.physics.moveToObject(bullet, target, 300);
        bullet.on('animationcomplete', () => {
            bullet.setActive(false);
            bullet.setVisible(false);
        });
    }
}
```

### Explanation:
- **Preload**: Loads images for towers, enemies, and bullets.
- **Create**: Sets up input to place towers, creates a group for bullets, and starts spawning enemies.
- **Update**: Checks if any tower can fire at an enemy within range and moves enemies along a simple path.
- **placeTower**: Places a tower at the clicked location.
- **spawnEnemy**: Spawns an enemy at the left side of the screen.
- **findNearestEnemy**: Finds the nearest enemy to a given tower.
- **fireBullet**: Fires a bullet from a tower towards a target enemy.

This code sets up a basic tower defense game where you can click to place towers, and they will automatically shoot at enemies moving horizontally across the screen. Adjustments can be made to the tower range, fire rate, and enemy movement as needed.

