}

function create() {
    // Create a particle emitter
    const particles = this.add.particles('particle');

    // Create an emitter configuration
    const emitter = particles.createEmitter({
        speed: { min: -400, max: 400 },
        angle: { min: 0, max: 360 },
        scale: { start: 0.5, end: 0 },
        blendMode: 'ADD',
        lifespan: 1000,
        quantity: 100,
        alpha: { start: 1, end: 0 },
