```javascript
// Define the configuration for the Phaser game
const config = {
    type: Phaser.AUTO,
    width: 800,
    height: 600,
    backgroundColor: '#2d2d2d',
    physics: {
        default: 'arcade'
    },
    scene: {
        preload: preload,
        create: create,
        update: update
    }
};

// Create a new Phaser game instance
const game = new Phaser.Game(config);

function preload() {
    // Preload any assets here if needed
}

function create() {
    // Define grid size
    const gridSize = 50;

    // Create some draggable shapes
    const shapes = [
        { x: 100, y: 100, color: 0xff0000 }, // Red circle
        { x: 200, y: 200, color: 0x00ff00 }, // Green square
        { x: 300, y: 300, color: 0x0000ff }  // Blue triangle
    ];

    shapes.forEach(shape => {
        let graphic;
        switch (shapes.indexOf(shape)) {
            case 0:
                // Circle
                graphic = this.add.circle(shape.x, shape.y, 25, shape.color);
                break;
            case 1:
                // Square
                graphic = this.add.rectangle(shape.x, shape.y, 50, 50, shape.color);
                break;
            case 2:
                // Triangle
                graphic = this.add.triangle(shape.x, shape.y, -25, 25, 25, 25, 0, -25, shape.color);
                break;
        }

        // Enable physics on the shape
        this.physics.world.enable(graphic);

        // Make the shape draggable
        graphic.setInteractive({ cursor: 'pointer' });
        this.input.setDraggable(graphic);

        // Handle drag events
        graphic.on('drag', function(pointer, dragX, dragY) {
            this.x = dragX;
            this.y = dragY;
        });

        graphic.on('dragend', function(pointer, dropX, dropY) {
            // Snap to grid
            this.x = Math.round(this.x / gridSize) * gridSize;
            this.y = Math.round(this.y / gridSize) * gridSize;
        });
    });
}

function update() {
    // Update logic here if needed
}
```

