        ]
    },
    "deep_cave": {
        "text": "You see a glowing light ahead. Approach it?",
        "choices": [
            {"text": "Yes", "next": "glowing_light", "require_flag": "fire_lit"},
            {"text": "No", "next": "leave_cave"}
        ]
    },
    "glowing_light": {
        "text": "You found a magical artifact! Congratulations!",
        "choices": []
    },
    "leave_cave": {
        "text": "You leave the cave and return to the entrance.",
        "choices": []
    },
    "explore_forest": {
        "text": "You explore further and find a hidden path.",
        "choices": []
    },
    "shelter": {
        "text": "You find a small shelter and spend the night.",
        "choices": []
    }
}

func _init():
    var current_node: String = "start"

    while true:
        var node_data: Dictionary = dialogue_tree[current_node]
        print(node_data["text"])

        if node_data["choices"].size() == 0:
            break

        for i in range(node_data["choices"].size()):
            print("%d: %s" % [i + 1, node_data["choices"][i]["text"]])

        var choice_index: int = int(input("Choose an option: ")) - 1
        assert(choice_index >= 0 and choice_index < node_data["choices"].size(), "Invalid choice index")

        var chosen_choice: Dictionary = node_data["choices"][choice_index]

        # Check if the choice requires a flag
        if "require_flag" in chosen_choice:
            assert(world_flags.has(chosen_choice["require_flag"]), "You cannot proceed without the required flag.")

        # Set any flags associated with the choice
        if "set_flag" in chosen_choice:
            world_flags[chosen_choice["set_flag"]] = true

        current_node = chosen_choice["next"]

    print("Dialogue ended.")
    quit()
