extends SceneTree

class_name CraftingSystem

# Define a simple Item class
class Item:
	var name: String
	var quantity: int

	func _init(name: String, quantity: int = 1):
		self.name = name
		self.quantity = quantity

	func __str__() -> String:
		return "%s x%d" % [name, quantity]

# Define a Recipe class
class Recipe:
	var name: String
	var ingredients: Array[Item]
	var result: Item

	func _init(name: String, ingredients: Array[Item], result: Item):
		self.name = name
		self.ingredients = ingredients
		self.result = result

func _init():
	var crafting_system := CraftingSystem.new()

	# Create some items
	var wood := Item.new("Wood", 5)
	var nail := Item.new("Nail", 10)
	var hammer := Item.new("Hammer")

	# Create a recipe
	var table_recipe := Recipe.new("Table", [wood, nail], hammer)

	# Inventory with sufficient ingredients
	var inventory_with_ingredients := [Item.new("Wood", 5), Item.new("Nail", 10)]

	# Inventory without sufficient ingredients
	var inventory_without_ingredients := [Item.new("Wood", 3), Item.new("Nail", 5)]

	# Test crafting with sufficient ingredients
	var crafted_item := crafting_system.craft(table_recipe, inventory_with_ingredients)
	assert(crafted_item != null, "Crafting should have succeeded with sufficient ingredients.")
	print("Crafted: %s" % crafted_item)

	# Test crafting with insufficient ingredients
	crafted_item = crafting_system.craft(table_recipe, inventory_without_ingredients)
	assert(crafted_item == null, "Crafting should have failed with insufficient ingredients.")
	print("Crafting failed as expected with insufficient ingredients.")

	quit()

func craft(recipe: Recipe, inventory: Array[Item]) -> Item:
	for ingredient in recipe.ingredients:
		var found := false
		for i in range(inventory.size()):
			if inventory[i].name == ingredient.name and inventory[i].quantity >= ingredient.quantity:
				inventory.write[i] = Item.new(inventory[i].name, inventory[i].quantity - ingredient.quantity)
				found = true
				break
		if not found:
			return null

	return Item.new(recipe.result.name, recipe.result.quantity)

```

This script defines a simple crafting system in Godot 4 using GDScript. It includes classes for `Item` and `Recipe`. The `_init()` function sets up a crafting recipe, tests crafting with both sufficient and insufficient ingredients, and asserts the expected outcomes. The `craft` function checks if the inventory contains the required ingredients and performs the crafting if possible. If any ingredient is missing or insufficient, it returns `null`. The script prints the results and quits after testing.

