		Item.new(name="Shield", rarity=1),
		Item.new(name="Potion", rarity=3),
		Item.new(name="Ring", rarity=2)
	]

	print("Original inventory:")
	for item in inventory:
		print("Name: %s, Rarity: %d" % [item.name, item.rarity])

	inventory.sort(custom_sort)

	print("\nSorted inventory:")
	for item in inventory:
		print("Name: %s, Rarity: %d" % [item.name, item.rarity])

	assert(is_sorted(inventory), "Inventory is not sorted correctly.")
	quit()

func custom_sort(a: Item, b: Item) -> int:
	if a.rarity == b.rarity:
		return a.name.locale_compare(b.name)
	return a.rarity - b.rarity

func is_sorted(inventory: Array[Item]) -> bool:
	for i in range(1, inventory.size()):
		if inventory[i-1].rarity > inventory[i].rarity:
			return false
		if inventory[i-1].rarity == inventory[i].rarity and inventory[i-1].name.locale_compare(inventory[i].name) > 0:
			return false
	return true
```

