extends SceneTree

class_name EventDispatcher

var _handlers: Dictionary[String, Array[Callable]] = {}

func _init():
    # Register some events
    register_event("test_event", self, "_on_test_event")

    # Dispatch the event
    dispatch_event("test_event", "Hello, World!")

    # Quit the application
    quit()

func register_event(event_name: String, target: Object, method: String):
    var callable = Callable(target, method)
    if not _handlers.has(event_name):
        _handlers[event_name] = []
    _handlers[event_name].append(callable)

func dispatch_event(event_name: String, var args: Variant = null) -> bool:
    if not _handlers.has(event_name):
        print("No handlers for event: %s" % event_name)
        return false

    var handlers = _handlers[event_name]
    var handler_ran: bool = false

    for handler in handlers:
        if handler.call_func(args):
            handler_ran = true

    assert(handler_ran, "At least one handler should have run for event: %s" % event_name)
    return handler_ran

func _on_test_event(message: String) -> bool:
    print("Test event received with message: %s" % message)
    return true
```

This script defines a simple event dispatcher within a `SceneTree` extension. It registers an event handler for `"test_event"`, dispatches this event with a message, and asserts that at least one handler was executed. The `_on_test_event` function is called when the event is dispatched, printing the received message and returning `true` to indicate successful execution. The script then quits the application.

